import java.io.BufferedReader; 
import java.io.IOException; 
import java.io.InputStreamReader; 
import java.util.*; 
import java.util.StringTokenizer; 

public class rps
{
    public static void main(String args[])
    {
        FastReader sc=new FastReader();
        int n=sc.nextInt();
        int[] alice = new int[3];
        int[] bob = new int[3];

        alice[0] = sc.nextInt(); // Alice's rock
        alice[1] = sc.nextInt(); // Alice's scissors
        alice[2] = sc.nextInt(); // Alice's paper

        bob[0] = sc.nextInt();   // Bob's rock
        bob[1] = sc.nextInt();   // Bob's scissors
        bob[2] = sc.nextInt();   // Bob's paper

        // Maximum wins for Alice:
        // Alice wins when:
        //   Alice rock (0) beats Bob scissors (1)
        //   Alice scissors (1) beats Bob paper (2)
        //   Alice paper (2) beats Bob rock (0)
        int maxWin = Math.min(alice[0], bob[1]) + 
                     Math.min(alice[1], bob[2]) + 
                     Math.min(alice[2], bob[0]);

        // Minimum wins for Alice:
        // We want to minimize Alice's wins, which means maximizing:
        // - Draws (same moves)
        // - Bob's wins (Alice loses)
        // Total rounds = n = wins + losses + draws
        // So min wins = n - max(draws + bob_wins)
        // Bob wins when:
        //   Bob rock (0) beats Alice scissors (1)
        //   Bob scissors (1) beats Alice paper (2)
        //   Bob paper (2) beats Alice rock (0)

        // To compute minimum wins, we can use the fact that:
        // min wins = n - max(draws + bob_wins)
        // draws = min(alice[i], bob[i]) for i in 0,1,2
        // bob_wins = min(bob[0], alice[1]) + min(bob[1], alice[2]) + min(bob[2], alice[0])

        int draws = Math.min(alice[0], bob[0]) + 
                    Math.min(alice[1], bob[1]) + 
                    Math.min(alice[2], bob[2]);

        int bobWins = Math.min(bob[0], alice[1]) + 
                      Math.min(bob[1], alice[2]) + 
                      Math.min(bob[2], alice[0]);

        int minWin = n - (draws + bobWins);

        System.out.println(minWin + " " + maxWin);
    }
}

class FastReader 
{ 
    BufferedReader br; 
    StringTokenizer st; 
    public FastReader() 
    { 
        br = new BufferedReader(new
        InputStreamReader(System.in)); 
    } 
    String next() 
    { 
        while (st == null || !st.hasMoreElements()) 
        { 
            try
            { 
                st = new StringTokenizer(br.readLine()); 
            } 
            catch (IOException e) 
            { 
                e.printStackTrace(); 
            } 
        } 
        return st.nextToken(); 
    } 
    int nextInt() 
    { 
        return Integer.parseInt(next()); 
    } 
    long nextLong() 
    { 
        return Long.parseLong(next()); 
    }
    double nextDouble() 
    { 
        return Double.parseDouble(next()); 
    } 
    String nextLine() 
    { 
        String str = ""; 
        try
        { 
            str = br.readLine(); 
        } 
        catch (IOException e) 
        { 
            e.printStackTrace(); 
        } 
        return str; 
    } 
}
